#!/usr/bin/env node
// Generated by Codebuff - Monorepo ZnIcon sprite generator + per-project chunk writer
//
// Generates, for every profile (shared + each app), one SVG sprite per icon
// family, filtered to the icons that profile actually uses, and writes them into
// that profile's own `dist/` folder:
//
//   dist/
//   ├── ui-core.js          (shared library build)
//   ├── ui-core.css
//   ├── zn-icon-core-filtered.svg   ← shared chunk (all families, common icons)
//   ├── zn-icon-core-filled.svg
//   ├── zn-icon-core-outlined.svg
//   └── ...
//
// Each app (zound-box, kitchensink, pwa-app2) then copies its own filtered
// sprites into its dist/ alongside the ui-core chunk. Apps consume the shared
// ui-core chunk and only their own used-icons chunk.

import { mkdir, readdir, readFile, writeFile, access, symlink, chmod } from 'node:fs/promises'
import { createRequire } from 'node:module'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const require = createRequire(import.meta.url)
const scriptDir = dirname(fileURLToPath(import.meta.url))
const outDir = resolve(scriptDir, '../src/icons')
const monorepoRoot = resolve(scriptDir, '..', '..', '..')
const iconsRoot = resolve(monorepoRoot, 'node_modules', '@material-design-icons', 'svg')

// Path to the icons.json profiles manifest (kept in the shared library so every
// project can resolve it through the workspace dependency).
const profilesFile = resolve(monorepoRoot, 'shared', 'ui-core', 'scripts', 'icons.json')

// Families of Material Design Icons
const FAMILIES = ['filled', 'outlined', 'round', 'sharp', 'two-tone']

const DEFAULT_VIEWBOX = '0 -960 960 960'

// Regex helpers - viewBox normalization
const RE_VIEWBOX_START = /^[.\s\S]*?<svg\b[^>]*>/
const RE_VIEWBOX_END = /<\/svg>\s*$/

/** Cargar iconos definidos en el manifiesto icons.json */
async function loadProfiles() {
  let data
  try {
    data = JSON.parse(await readFile(profilesFile, 'utf8'))
  } catch {
    // Sin manifiesto → modo de compatibilidad (PERFILES hardcodeados)
    return {
      shared: new Set([
        'bolt', 'check', 'close', 'dark_mode', 'diamond', 'download',
        'favorite', 'home', 'keyboard_arrow_down', 'light_mode',
        'more_vert', 'music_note', 'palette', 'pause', 'play_arrow',
        'settings', 'skip_next'
      ]),
      kitchensink: new Set([
        'bolt', 'check', 'close', 'dark_mode', 'diamond', 'download',
        'favorite', 'home', 'keyboard_arrow_down', 'light_mode',
        'more_vert', 'music_note', 'palette', 'pause', 'play_arrow',
        'settings', 'skip_next'
      ]),
      'zound-box': new Set([
        'home', 'pause', 'play_arrow', 'settings', 'skip_next',
        'volume_2', 'volume_high', 'volume_low', 'equalizer'
      ]),
      'pwa-app2': new Set([
        'home', 'settings', 'play_arrow', 'pause', 'next_week', 'menu'
      ])
    }
  }

  const profiles = {}
  for (const [key, names] of Object.entries(data)) {
    profiles[key] = new Set(Array.isArray(names) ? names : [])
  }
  return profiles
}

/** Cargar names files del proyecto local (para llenar toda una familia) */
const namesCache = new Map()
async function loadFamilyNames(family) {
  if (namesCache.has(family)) return namesCache.get(family)
  const path = join(scriptDir, '..', 'src', 'icons', 'names-' + family + '.js')
  try {
    const data = await readFile(path, 'utf8')
    const match = data.match(/export default\s*\[([\s\S]*)\]/)
    if (match) {
      const inner = match[1]
      const names = inner.split(',')
        .map(s => s.replace(/^['"]|["']$/g, '').trim())
        .filter(s => s.length > 0)
      namesCache.set(family, names)
      return names
    }
    namesCache.set(family, [])
    return []
  } catch {
    namesCache.set(family, [])
    return []
  }
}

/** Hace el símbolo SVG. */
function makeSymbol(id, svg) {
  const inner = svg.replace(RE_VIEWBOX_START, '').replace(RE_VIEWBOX_END, '').trim()
  // Normalizar viewBox a 0 0 24 24 (MD3 standard) independientemente del original
  return '  <symbol id="' + id + '" viewBox="0 0 24 24">' + inner + '</symbol>'
}

/**
 * Genera un sprite filtrado por nombres, en un output dir.
 * @param {Set<string>} names
 * @param {string} family
 * @param {string} outDir
 */
async function generateFiltered(names, family, outDir) {
  const allNames = await loadFamilyNames(family)
  const validNames = new Set(allNames.filter(n => names.has(n)))

  const familyDir = resolve(iconsRoot, family)
  const files = await readdir(familyDir)

  // Mapear nombre archivo → svg
  const svgMap = new Map()
  for (const f of files) {
    if (f.endsWith('.svg')) {
      svgMap.set(f.replace('.svg', ''), await readFile(join(familyDir, f), 'utf8'))
    }
  }

  const sortedAll = [...allNames].sort()
  const sortedValid = [...validNames].sort()

  const nameToSvg = new Map()
  for (let i = 0; i < sortedAll.length; i++) {
    const name = sortedAll[i]
    if (validNames.has(name)) {
      const svg = nameToSvg.get(name) || svgMap.get(name)
      if (svg) {
        nameToSvg.set(name, svg)
      }
    }
  }

  const symbols = []
  const finalNames = []
  for (const name of sortedAll) {
    if (validNames.has(name)) {
      const svg = nameToSvg.get(name)
      if (svg) {
        finalNames.push(name)
        const id = 'zn-icon-' + family + '-' + name
        symbols.push(makeSymbol(id, svg))
      }
    }
  }
  console.error('DEBUG generateFiltered: validNames=' + validNames.size + ' allNames=' + allNames.length + ' nameToSvg=' + nameToSvg.size + ' finalNames=' + finalNames.length)
  if (finalNames.length === 0) {
    // Fallback: sprite completo de toda la familia
    return await generateFullFamily(family, outDir)
  }

  const sprite = '<!-- Generated by generate-icons.mjs -->\n' +
    '<svg xmlns="http://www.w3.org/2000/svg" id="zn-icon-sprite-' + family + '" aria-hidden="true">\n' +
    symbols.join('\n') + '\n' +
    '</svg>\n'
  const namesModule = '// Generated by generate-icons.mjs\n' +
    'export default ' + JSON.stringify(finalNames, null, 0) + '\n'

  await writeFile(join(outDir, 'zn-icon-' + family + '.svg'), sprite, 'utf8')
  await writeFile(join(outDir, 'zn-icon-names-' + family + '.js'), namesModule, 'utf8')

  return finalNames.length
}

/** Genera sprite completo de toda la familia (fallback) */
async function generateFullFamily(family, outDir) {
  const allNames = await loadFamilyNames(family)
  const familyDir = resolve(iconsRoot, family)
  const files = await readdir(familyDir)

  const symbols = []
  const finalNames = []
  for (let i = 0; i < allNames.length; i++) {
    const name = allNames[i]
    const file = files[i]
    if (file) {
      const svg = await readFile(join(familyDir, file), 'utf8')
      finalNames.push(name)
      const id = 'zn-icon-' + family + '-' + name
      symbols.push(makeSymbol(id, svg))
    }
  }

  if (symbols.length === 0) return 0

  const sprite = '<!-- Generated by generate-icons.mjs -->\n' +
    '<svg xmlns="http://www.w3.org/2000/svg" id="zn-icon-sprite-' + family + '" aria-hidden="true">\n' +
    symbols.join('\n') + '\n' +
    '</svg>\n'
  const namesModule = '// Generated by generate-icons.mjs\n' +
    'export default ' + JSON.stringify(finalNames, null, 0) + '\n'

  await writeFile(join(outDir, 'zn-icon-' + family + '.svg'), sprite, 'utf8')
  await writeFile(join(outDir, 'zn-icon-names-' + family + '.js'), namesModule, 'utf8')

  return finalNames.length
}

async function main() {
  const args = process.argv.slice(2)
  const filterIdx = args.findIndex(a => a === '--filter')
  const profileIdx = args.findIndex(a => a === '--profile')
  const outIdx = args.findIndex(a => a === '--out')

  const filterNames = filterIdx >= 0
    ? (args[filterIdx + 1] ? args[filterIdx + 1].split(',').map(n => n.trim()).filter(Boolean) : [])
    : []

  let profile = null
  if (profileIdx >= 0) profile = args[profileIdx + 1] || null

  let outDirArg = outIdx >= 0 ? args[outIdx + 1] : null

  const profiles = await loadProfiles()

  // 1. Modo "shared": genera el sprite filtrado al core para todos los usuarios
  if (profile === 'shared' || (!profile && filterNames.length === 0 && !outDirArg)) {
    const icons = new Set(profiles.shared || [])
    console.error('DEBUG profile=shared icons:', icons.size)
    for (const family of FAMILIES) {
      console.error('DEBUG generating family:', family)
      await generateFiltered(icons, family, outDir)
    }
    console.log('📦 Sprite del core generado en ' + outDir)
    return
  }

  // 2. Modo "core-only": solo el sprite del core, sin perfiles
  if (profile === 'core') {
    for (const family of FAMILIES) {
      await generateFiltered(profiles.shared || new Set(), family, outDir)
    }
    console.log('📦 Sprite del core solo generado en ' + outDir)
    return
  }

  // 3. Modo perfil: genera el chunk de iconos del perfil en su propio dist/
  if (profile && profile.startsWith('app:')) {
    const appName = profile.slice(4)
    const icons = new Set(profiles[appName] || [])
    if (!outDirArg) {
      // Por defecto el chunk va al dist del proyecto que consume la librería
      outDirArg = join(monorepoRoot, appName, 'dist')
    }
    await mkdir(outDirArg, { recursive: true })
    let total = 0
    for (const family of FAMILIES) {
      const c = await generateFiltered(icons, family, outDirArg)
      total += c
      console.log('  ' + family.padEnd(9) + c + ' iconos -> ' + outDirArg)
    }
    console.log('Total: ' + total + ' iconos (chunk de ' + appName + ')')
    return
  }

  // 4. Modo filtrado explícito
  if (filterNames.length > 0) {
    const out = outDirArg || outDir
    await mkdir(out, { recursive: true })
    let total = 0
    for (const family of FAMILIES) {
      const c = await generateFiltered(new Set(filterNames), family, out)
      total += c
      console.log('  ' + family.padEnd(9) + c + ' iconos')
    }
    console.log('Total: ' + total + ' iconos (filtrados)')
    return
  }

  console.error('Modo no reconocido; usa --profile app:NOMBRE o --filter NOMBRE1,NOMBRE2')
  process.exitCode = 1
}

main().catch(e => { console.error(e.message); process.exitCode = 1 })
